import numpy as np
from rdkit import Chem
lines=open("relaxed.xyz").read().split("\n")[2:]
atoms=[];coords=[]
for l in lines:
    if l.strip():
        p=l.split(); atoms.append(p[0]); coords.append([float(x) for x in p[1:4]])
