mol=Chem.MolFromXYZBlock(open("relaxed.xyz").read())
# bonded set from our known connectivity: rebuild quickly
mf=Chem.MolFromMolFile("ipr.mol", removeHs=False)
fb=[(b.GetBeginAtomIdx(),b.GetEndAtomIdx()) for b in mf.GetBonds()]
nF=mf.GetNumAtoms()
bonds=set()
for off in (0,nF,2*nF):
    for a,b in fb: bonds.add(tuple(sorted((a+off,b+off))))
core=[(195,196),(196,197),(197,198),(195,199),(198,200),(196,201),(197,201),(0,199),(65,200),(130,201)]
for a,b in core: bonds.add(tuple(sorted((a,b))))
d=np.linalg.norm(P[:,None,:]-P[None,:,:],axis=-1)
best=99; pair=None
for i in range(len(P)):
    for j in range(i+1,len(P)):
        if (i,j) in bonds: continue
        # skip 1-3
        if d[i,j]<best:
            # check 1-3
            ni={x for (a,b) in bonds for x in ((b,) if a==i else (a,) if b==i else ())}
            nj={x for (a,b) in bonds for x in ((b,) if a==j else (a,) if b==j else ())}
            if ni & nj: continue
            best=d[i,j]; pair=(i,j,atoms[i],atoms[j])
print("min non-bonded (excl 1-3):", round(best,2), pair)
